def _models(blocks):
    (z, l, q, r, p, c) = blocks
    cross = (p[:, :, None] * c[:, None, :]).reshape(len(z), -1)
    ds = _dist(z)
    fs = [_ones(np.c_[p, c, cross]), _ones(np.c_[z, p, c, cross]), _ones(np.c_[p, c, (q * r).sum(1)]), np.ones((len(z), 1))]
    for (ix, F) in enumerate(fs):
